"""Writes the JSON files for Core False Beliefs cards 2-22 (card 1 is tools/core/001.json).
Each group goes in its own folder so build_core_cards.py can build it as one set."""
import json
from pathlib import Path
ROOT = Path(__file__).resolve().parents[1]
SETS = {"My Worth": "core", "My Strength": "core-strength", "Other People": "core-people",
        "The World & the Future": "core-world", "Rules I Live By": "core-rules",
        "After Painful Experiences": "core-painful"}
CARDS = []
def card(**d):
    CARDS.append(d)

# ---------------- MY WORTH ----------------
card(num=2, group="My Worth", belief="I am worthless.", file="I-Am-Worthless",
 origins="Many people learn this belief from the way they were treated: being called names, put down, ignored, used, or compared unfavorably with others. When love depended on grades, looks, money, or behavior, a child can conclude that a person is only worth what he or she produces. Losses such as a divorce, a job loss, a disability, or growing older can reawaken it later. Our culture adds to it by measuring people by success, popularity, and appearance.",
 teaches="Scripture places a person’s worth in God, not in performance. Jesus said that not one sparrow falls apart from the Father, and that you are worth more than many sparrows. God calls His people precious and honored in His sight. The clearest measure of your worth is the price that was paid for you: not silver or gold, but the precious blood of Christ. Your worth was settled by God before you did anything right or wrong, and nothing you do can add to or subtract from His love.",
 key="Matthew 10:29–31", also=["1 Peter 1:18–19", "Isaiah 43:4", "Psalm 8:4–5", "Romans 5:8"],
 self_statements=["I am not worth anything.", "Other people matter; I don’t.", "If I disappeared, no one would notice.", "I have nothing to offer.", "I only matter when I am useful.", "I don’t deserve good things."],
 errors=[["Labeling", "Giving myself a single word, “worthless,” that ignores everything else that is true about me."], ["Mental filter", "Remembering every failure or rejection and overlooking the times I helped, loved, or was valued."], ["Emotional reasoning", "Concluding I have no worth because I feel worthless."], ["Comparison", "Measuring my value against other people’s gifts, looks, or success."]],
 questions=["Who decides what a person is worth: other people, my feelings, or God?", "Where did I first learn that I was worthless?", "Would I call a friend worthless for the same reasons I call myself worthless?", "What price did God pay for me, and what does that say about my value?", "Is my worth something I earn, or something I was given?", "What would change in my day if I believed I was precious to God?"],
 truth="My worth does not come from what I do, how I look, or what others say. God made me, values me, and paid the highest price for me in Christ. I may feel worthless at times, but feelings are not the final word. I am precious and honored in His sight.",
 hw_truths=["I am worth more than many sparrows.", "I was bought with the precious blood of Christ.", "My worth was given, not earned.", "Feeling worthless is not the same as being worthless.", "I am precious and honored in God’s sight.", "I can treat myself as someone God values."],
 log=["When I felt worthless", "Each day, write one moment when you felt worthless. Note what triggered it and write one truth from this card that answers it."],
 actions=[["Write your “worth” list.", "List five things God says about you from the verses on this card. Read the list each morning for one week."], ["Treat yourself as valuable for one day.", "Do one ordinary act of care for yourself, such as a good meal, rest, or a walk, as if you were caring for someone God loves."], ["Notice the put-downs.", "Each time you call yourself worthless or stupid, stop and replace it with a sentence you would say to a friend."], ["Let someone see your value.", "Accept one compliment this week without arguing. Simply say, “Thank you.”"]],
 tracker="A moment I treated myself as valuable",
 prayer="Father, I have measured my worth by what others said and by what I could do. Thank You that You call me precious and that Christ gave Himself for me. When I feel worthless, help me believe what You say instead of what I feel. Amen.",
 songs=["who", "greater", "younger", "assurance"],
 pearls=["self-esteem-low", "love-by-god", "christ-sacrifice-of", "god-all-loving", "thinking-healthy"],
 godly_counsel=[24, 17], reading="self-esteem-low", listening="Depression",
 hw_questions=["Who decides what I am worth?", "Where did I learn that I was worthless?", "Would I say this about a friend?", "What price did God pay for me?", "Is my worth earned or given?", "What would change if I believed I was precious?"],
 name_example=["Matthew 10:29–31", "<strong>David</strong> can write: “God sees every sparrow, and I am worth more than many sparrows. My worth is settled by Him.”"],
 hw_scriptures=["Matthew 10:29–31", "1 Peter 1:18–19", "Isaiah 43:4"])

card(num=3, group="My Worth", belief="I am not lovable.", file="I-Am-Not-Lovable",
 origins="This belief often grows out of love that was missing, inconsistent, or conditional. A parent who was cold, absent, harsh, or only affectionate when we behaved well can leave the impression that we are hard to love. Rejection by a spouse, friends, or a church can deepen it. People who hold this belief often keep others at a distance or try very hard to earn affection, and both can make relationships feel even less safe.",
 teaches="The Bible teaches that God’s love does not begin with our lovableness. He showed His love by sending His Son while we were still far from Him. Paul was convinced that nothing in all creation can separate us from the love of God in Christ Jesus. Zephaniah pictures God rejoicing over His people with singing. God does not love you because you finally became lovable; His love is what makes you beloved. People may fail to love you well, but their failure does not define your lovability.",
 key="Romans 8:38–39", also=["1 John 4:9–10", "Zephaniah 3:17", "Ephesians 3:17–19", "Psalm 27:10"],
 self_statements=["If people really knew me, they would not love me.", "I am too much, or not enough, to be loved.", "Love always runs out for me.", "I have to earn every bit of affection.", "People only put up with me.", "Even God must find me hard to love."],
 errors=[["Overgeneralization", "Deciding that because some people did not love me well, no one can."], ["Personalization", "Assuming others’ failure to love me is proof that something in me is unlovable."], ["Mind reading", "Believing I know that people secretly dislike me."], ["Discounting the positive", "Brushing aside kindness as pity or politeness."]],
 questions=["Whose love was missing or conditional when I was growing up?", "Does someone else’s failure to love me prove I am unlovable?", "What evidence is there that people have cared about me?", "Did God wait for me to become lovable before He loved me?", "How might I be pushing love away to protect myself?", "What would it look like to receive love without earning it?"],
 truth="Some people did not love me well, and that hurt. But their failure is not a verdict on me. God loved me before I did anything to deserve it, and nothing can separate me from His love in Christ. I am loved, and I can learn to receive love from God and from others.",
 hw_truths=["Nothing can separate me from God’s love.", "God loved me first.", "Others’ failures to love me do not define me.", "I do not have to earn love.", "God rejoices over me.", "I can let safe people care about me."],
 log=["Love I noticed today", "Each evening, write one way God or another person showed care for you, even something small. Note how you responded."],
 actions=[["Make a “loved by God” list.", "Write down every verse on this card that speaks of God’s love. Read one aloud each morning."], ["Receive one kindness.", "When someone is kind to you this week, do not deflect it. Thank them and let it land."], ["Reach out once.", "Contact one safe person you have been keeping at a distance and suggest coffee, a call, or a walk."], ["Notice the old voice.", "When you think “I’m unlovable,” ask whose voice that sounds like, and answer it with Romans 8:38–39."]],
 tracker="A time I let myself be loved",
 prayer="Lord, I have believed I am too broken or too much to be loved. Thank You that You loved me first and that nothing can separate me from Your love. Heal the places where love was missing, and help me receive Your love and the love of the people You place in my life. Amen.",
 songs=["father", "stays", "love", "lovesme"],
 pearls=["love-by-god", "god-all-loving", "loneliness", "self-esteem-low", "friendship"],
 godly_counsel=[17, 24], reading="love-by-god", listening="Depression",
 hw_questions=["Where was love missing or conditional for me?", "Does someone’s failure to love me prove I am unlovable?", "What evidence shows people have cared about me?", "Did God wait for me to be lovable?", "How might I push love away?", "What would receiving love look like?"],
 name_example=["Romans 8:38–39", "<strong>Linda</strong> can write: “Nothing in all creation can separate me from God’s love in Christ, not even my worst days.”"],
 hw_scriptures=["Romans 8:38–39", "1 John 4:9–10", "Zephaniah 3:17"])

card(num=4, group="My Worth", belief="I am a failure.", file="I-Am-A-Failure",
 origins="This belief often comes from high expectations, harsh criticism, or being compared with brothers, sisters, or classmates. It can take root after a major setback such as a divorce, a business loss, a lost job, or a broken promise to ourselves. Over time a person stops saying “I failed at that” and starts saying “I am a failure,” as though one chapter were the whole story.",
 teaches="Scripture is full of people who failed: Moses, David, Elijah, Peter, and many others. God did not discard them. He restored them and used them. The Bible says a righteous person may fall seven times and still get up. Paul learned that God’s power is made perfect in weakness. God’s mercies are new every morning. Failing at something is part of being human; it is not your identity. In Christ, failure becomes a place where grace can work.",
 key="2 Corinthians 12:9", also=["Proverbs 24:16", "Lamentations 3:22–23", "Philippians 3:13–14", "Psalm 37:23–24"],
 self_statements=["I never get anything right.", "Everyone else succeeds; I don’t.", "Why try? I will only fail again.", "I have wasted my life.", "I let everyone down.", "One mistake ruins everything."],
 errors=[["Labeling", "Turning “I failed” into “I am a failure.”"], ["All-or-nothing thinking", "Believing that anything less than complete success is total failure."], ["Fortune telling", "Predicting that I will fail before I even try."], ["Mental filter", "Remembering my failures and forgetting what I have done well."]],
 questions=["What exactly did I fail at, and is that the same as being a failure?", "What have I done well, even in small ways?", "Who taught me that mistakes make me a failure?", "How did God treat Peter, David, or Moses after they failed?", "What did I learn from this failure?", "What is one small next step I can take?"],
 truth="I have failed at some things, like every person who has ever lived. But a failure is something that happened, not who I am. God restores people who fall, and His grace is enough for me. I can get up, learn, and take the next step with His help.",
 hw_truths=["Failing is not the same as being a failure.", "God’s grace is enough for me.", "His mercies are new every morning.", "The righteous fall and get up again.", "I can learn from mistakes.", "God is not finished with me."],
 log=["What I tried and what I learned", "Each day, write one thing you attempted, how it went, and one thing you learned, whether it succeeded or not."],
 actions=[["Change the label.", "Write “I am a failure.” Then rewrite it as a specific event: “I failed at ___ on ___.” Notice the difference."], ["List what you have done well.", "Write ten things you have accomplished or done faithfully, large or small. Ask someone who knows you to add two."], ["Try something small.", "Choose one small task you have been avoiding because you might fail. Do it this week and note what happened."], ["Read a restoration story.", "Read John 21:15–19, where Jesus restores Peter. Write what it tells you about how God treats failure."]],
 tracker="Something I tried",
 prayer="Lord, I have failed many times, and I have let failure tell me who I am. Thank You that Your grace is enough and that Your power works in my weakness. Help me get up, learn, and keep walking with You. Amen.",
 songs=["wins", "name", "broken", "faithful"],
 pearls=["weakness", "grace", "self-esteem-low", "strength", "hardship"],
 godly_counsel=[24, 30], reading="grace", listening="Depression",
 hw_questions=["What did I fail at, specifically?", "What have I done well?", "Who taught me mistakes make me a failure?", "How did God treat people in the Bible who failed?", "What did I learn?", "What small next step can I take?"],
 name_example=["2 Corinthians 12:9", "<strong>Mark</strong> can write: “God’s grace is enough for me. My weakness is where His power can work.”"],
 hw_scriptures=["2 Corinthians 12:9", "Proverbs 24:16", "Lamentations 3:22–23"])

# ---------------- MY STRENGTH ----------------
card(num=5, group="My Strength", belief="I am powerless.", file="I-Am-Powerless",
 origins="People often learn powerlessness in situations where they truly had no control: growing up with an abusive or addicted parent, being bullied, living through poverty or illness, or being trapped in a controlling relationship. The lesson “nothing I do makes a difference” can follow a person into adulthood, even after the situation has changed and real choices have returned.",
 teaches="The Bible is honest that we are limited and cannot save ourselves. But it never leaves God’s people helpless. God gives power to the faint and strength to the weak. Paul said he could do all things through Christ who strengthens him. God has not given us a spirit of fear, but of power, love, and self-control. In Christ we are not powerless; we are dependent on a powerful God who works within us. Some things are outside our control, but we are never without God’s help or without some choice.",
 key="Isaiah 40:29–31", also=["Philippians 4:13", "2 Timothy 1:7", "Ephesians 3:20", "Joshua 1:9"],
 self_statements=["Nothing I do makes a difference.", "Things just happen to me.", "I have no say in my own life.", "Other people control everything.", "I can’t change anything.", "Why bother trying?"],
 errors=[["Overgeneralization", "Believing that because I was powerless once, I am powerless in everything."], ["All-or-nothing thinking", "Thinking that if I cannot control everything, I control nothing."], ["Fortune telling", "Predicting that my efforts will not matter before I try."], ["Discounting the positive", "Overlooking the choices I do make every day."]],
 questions=["When did I first feel truly powerless, and is that situation still true today?", "What choices do I have right now, even small ones?", "What is in my control, and what is not?", "What does God say He gives to the weak?", "When have I made a difference, even in a small way?", "Who could help me with what I cannot do alone?"],
 truth="There are things I cannot control, and there were times I truly had no power. But I am not powerless now. God gives strength to the weak, and in Christ I can take the steps in front of me. I have choices, and I have a God who works within me.",
 hw_truths=["God gives strength to the weary.", "I can do all things through Christ.", "God gave me power, love, and self-control.", "I always have some choice.", "What happened then is not the same as now.", "I can ask for help and still be strong."],
 log=["Choices I made today", "Each evening, list three choices you made today, however small, and note what difference each one made."],
 actions=[["Sort what you can and cannot control.", "Draw two columns. List what worries you, then place each item under “In my control” or “Not in my control.” Pray over the second; act on the first."], ["Take one action.", "Pick one item in your control and take one small step on it this week."], ["Use your voice once.", "State one honest preference or need to someone this week, such as where to eat or what you need."], ["Get the right help.", "If someone is controlling or harming you, talk privately with a counselor, pastor, or trusted person about safe next steps."]],
 tracker="A choice I made",
 prayer="Lord, I have felt helpless for so long. Thank You that You give strength to the weary and power to the weak. Show me the choices I have, give me courage to take them, and help me rest in You for what I cannot control. Amen.",
 songs=["ourgod", "power", "fear", "victory"],
 pearls=["strength", "weakness", "god-all-powerful", "help", "fear"],
 godly_counsel=[33, 5], reading="strength", listening="Depression",
 hw_questions=["Is the situation that made me powerless still true?", "What choices do I have right now?", "What is in my control?", "What does God give to the weak?", "When have I made a difference?", "Who could help me?"],
 name_example=["Isaiah 40:29–31", "<strong>Karen</strong> can write: “God gives power to the faint. When I am weak, I can wait on Him and find new strength.”"],
 hw_scriptures=["Isaiah 40:29–31", "Philippians 4:13", "2 Timothy 1:7"])

card(num=6, group="My Strength", belief="I cannot handle this.", file="I-Cannot-Handle-This",
 origins="This belief often appears when stress piles up: illness, caring for a loved one, money problems, grief, or several crises at once. It can also come from growing up without being allowed to face difficulties, or from being overwhelmed as a child with burdens too heavy for a child to carry. The body’s alarm system then fires quickly, and the thought “I can’t handle this” arrives before we have even tried.",
 teaches="Scripture does not promise that life will be easy, but it does promise that God will not leave us to carry it alone. God is our refuge and strength, an ever-present help in trouble. He tells His people not to fear, because He will strengthen and uphold them. Paul described being hard pressed but not crushed. Jesus invites the weary to come to Him and find rest. You may not be able to handle this by yourself, but you are not by yourself.",
 key="Isaiah 41:10", also=["Psalm 46:1", "1 Corinthians 10:13", "2 Corinthians 4:8–9", "Matthew 11:28–30"],
 self_statements=["This is too much for me.", "I’m going to fall apart.", "I can’t cope with one more thing.", "Other people could handle this, but not me.", "I need to escape.", "If this goes on, I’ll break."],
 errors=[["Catastrophizing", "Imagining the worst possible outcome and assuming I will not survive it."], ["Fortune telling", "Predicting that I will fall apart before it happens."], ["Emotional reasoning", "Believing I can’t cope because I feel overwhelmed."], ["Discounting the positive", "Forgetting the hard things I have already gotten through."]],
 questions=["What hard things have I already gotten through?", "What is the next small step, not the whole mountain?", "Am I trying to handle tomorrow’s problems today?", "What does God promise to those who are overwhelmed?", "Who can help carry part of this load?", "What would I tell a friend in my situation?"],
 truth="This is hard, and I feel overwhelmed. But I have gotten through hard things before, and God has promised to strengthen and uphold me. I don’t have to handle everything at once. I can take the next step, ask for help, and lean on Him.",
 hw_truths=["God will strengthen and help me.", "I am hard pressed but not crushed.", "I only need to take the next step.", "I have survived hard things before.", "I can share the load.", "Jesus gives rest to the weary."],
 log=["What I got through today", "Each evening, write one hard moment from the day and how you got through it, even if it was messy."],
 actions=[["Break it down.", "Write the whole situation at the top of a page. Below it, list the smallest next steps. Do only the first one today."], ["Remember past strength.", "List three hard things you have already survived. Write how God helped you through each one."], ["Ask for one specific help.", "Ask one person for one concrete thing, such as a meal, a ride, or an hour of company."], ["Practice slowing down.", "When you feel overwhelmed, stop, breathe slowly for one minute, and pray Isaiah 41:10 aloud."]],
 tracker="A hard moment I got through",
 prayer="Lord, this feels like more than I can carry. You promised to strengthen me, help me, and hold me up. Show me the next step, send help where I need it, and give me rest in You. Amen.",
 songs=["held", "battle", "alone", "eyes"],
 pearls=["troubles", "hardship", "strength", "anxiety-worry", "help"],
 godly_counsel=[30, 33], reading="troubles", listening="Anxiety",
 hw_questions=["What hard things have I already gotten through?", "What is the next small step?", "Am I carrying tomorrow’s problems today?", "What does God promise the overwhelmed?", "Who can share the load?", "What would I tell a friend?"],
 name_example=["Isaiah 41:10", "<strong>James</strong> can write: “God is with me. He will strengthen me, help me, and hold me up today.”"],
 hw_scriptures=["Isaiah 41:10", "Psalm 46:1", "2 Corinthians 4:8–9"])

card(num=7, group="My Strength", belief="I cannot make it on my own.", file="I-Cannot-Make-It-On-My-Own",
 origins="This belief can develop when a person was overprotected, never allowed to make decisions, or told they were incapable. It can also follow years of depending on a spouse, parent, or caregiver, or a loss that left someone suddenly alone. The belief is partly true, because we all need God and other people. It becomes harmful when it turns into fear of being alone, staying in unhealthy relationships, or giving up our own decisions.",
 teaches="Scripture honors healthy dependence. Two are better than one, and God settles the lonely in families. Our ultimate dependence is on the Lord, who holds our right hand and helps us. But the Bible also calls each person to carry his own load and to grow in maturity. Needing God and others does not mean you are helpless. God has given you abilities, judgment, and His Spirit. You can lean on Him and on safe people while also taking responsibility for your own life.",
 key="Isaiah 41:13", also=["Psalm 121:1–2", "Ecclesiastes 4:9–10", "Galatians 6:4–5", "2 Corinthians 3:5"],
 self_statements=["I need someone to take care of me.", "I can’t make decisions on my own.", "If I lose this person, I’ll fall apart.", "I’m not capable of running my life.", "I’ll put up with anything rather than be alone.", "Others know better than I do."],
 errors=[["All-or-nothing thinking", "Believing that if I need help with some things, I can’t do anything on my own."], ["Fortune telling", "Predicting that I will fail if I try to stand on my own."], ["Discounting the positive", "Overlooking the things I already do well by myself."], ["Catastrophizing", "Imagining that being alone would be unbearable."]],
 questions=["What do I already do on my own, even if I don’t notice it?", "Who taught me that I couldn’t manage by myself?", "Is there a difference between needing help and being helpless?", "Am I staying in anything unhealthy because I fear being alone?", "What does God say about His help and my responsibility?", "What is one decision I can make myself this week?"],
 truth="I need God, and I need people; that is how He made me. But needing help does not mean I am helpless. God holds my hand and has given me abilities and judgment. I can take responsibility for my life, make my own decisions, and still lean on Him and on safe people.",
 hw_truths=["My help comes from the Lord.", "Needing help is not the same as being helpless.", "God has given me abilities and judgment.", "I can make decisions and learn from them.", "Healthy relationships are chosen, not clung to.", "God holds my right hand."],
 log=["Things I did on my own", "Each day, write one thing you handled or decided yourself, and how it went."],
 actions=[["List what you already do.", "Write down every task you already handle on your own. Include small things. Read the list when you feel helpless."], ["Make one decision yourself.", "Choose one decision you would normally hand to someone else, make it, and notice what happens."], ["Learn one new skill.", "Pick one practical skill, such as paying a bill online or cooking a simple meal, and learn it this week."], ["Widen your circle.", "Add one more safe person or group to your life so you are not relying on just one person."]],
 tracker="Something I handled myself",
 prayer="Lord, I lean on You, and I thank You for the people You have given me. Help me see the abilities You have placed in me. Give me courage to take responsibility, make decisions, and grow, knowing You hold my hand. Amen.",
 songs=["knows", "thrive", "glorious", "lives"],
 pearls=["help", "strength", "trust", "guidance", "plans"],
 godly_counsel=[33, 29], reading="help", listening="Anxiety",
 hw_questions=["What do I already do on my own?", "Who taught me I couldn’t manage?", "What is the difference between needing help and being helpless?", "Am I staying in something unhealthy out of fear?", "What does God say about His help and my part?", "What decision can I make myself?"],
 name_example=["Isaiah 41:13", "<strong>Maria</strong> can write: “The Lord holds my right hand. With His help, I can take the next step myself.”"],
 hw_scriptures=["Isaiah 41:13", "Psalm 121:1–2", "Galatians 6:4–5"])

# ---------------- OTHER PEOPLE ----------------
card(num=8, group="Other People", belief="I don’t belong.", file="I-Dont-Belong",
 origins="Feeling like an outsider can come from moving often, being left out at school, growing up in a family where we felt different, or being excluded because of our background, looks, or abilities. Some people felt unwanted at home or were treated as the “odd one.” Later, the belief can make us hold back in groups, read rejection into neutral situations, or leave before we can be left.",
 teaches="Scripture says that in Christ we are no longer strangers and foreigners, but members of God’s household. God arranged the members of the body exactly as He wanted, and each part belongs to the others. He settles the lonely in families. Peter wrote to scattered people that they were now God’s chosen people. Belonging is not something you have to win by fitting in; it is something God gives. You may still need time and effort to find your place among people, but you already have a place in His family.",
 key="Ephesians 2:19", also=["1 Corinthians 12:18", "Romans 12:5", "1 Peter 2:9–10", "Psalm 68:6"],
 self_statements=["I never fit in anywhere.", "Everyone else has their group.", "People just tolerate me.", "I’m always on the outside looking in.", "If I speak up, they’ll see I don’t belong.", "I’m different from everyone."],
 errors=[["Mind reading", "Assuming others think I don’t belong without asking."], ["Overgeneralization", "Deciding I don’t belong anywhere because I felt left out somewhere."], ["Personalization", "Taking ordinary group dynamics as rejection of me."], ["Emotional reasoning", "Believing I am an outsider because I feel like one."]],
 questions=["Where and when did I first feel I didn’t belong?", "Is it true that I don’t belong anywhere, or only in some places?", "What evidence is there that someone wants me around?", "Am I holding back in ways that make belonging harder?", "What does God say about my place in His family?", "Where could I begin to belong, even a little?"],
 truth="I have felt left out, and that hurt. But I am not an outsider to God. In Christ I am a member of His household, placed in His body on purpose. I can take small steps toward people, knowing my true place is already secure.",
 hw_truths=["I am a member of God’s household.", "God placed me in His body on purpose.", "I belong to Christ and to His people.", "Feeling like an outsider is not the same as being one.", "Belonging grows with time and small steps.", "God settles the lonely in families."],
 log=["Moments of connection", "Each day, write one moment when you felt even a little connected to someone, and what helped."],
 actions=[["Show up three times.", "Choose one group, such as a class, Bible study, or volunteer team, and attend three times before deciding whether you belong."], ["Contribute something.", "Offer one small help or skill in a group this week. Belonging often grows through serving together."], ["Ask instead of assuming.", "When you sense rejection, gently check it out or wait for more evidence before concluding."], ["Invite someone.", "Invite one person for coffee or a walk. Belonging often starts with one relationship."]],
 tracker="A moment I felt I belonged",
 prayer="Father, I have felt like an outsider for so long. Thank You that in Christ I am a member of Your household. Lead me to people where I can grow roots, give me courage to show up, and help me rest in the place You have already given me. Amen.",
 songs=["body", "who", "stays", "assurance"],
 pearls=["loneliness", "church", "friendship", "chosen-elect", "love-for-others"],
 godly_counsel=[17, 24], reading="loneliness", listening="Depression",
 hw_questions=["When did I first feel I didn’t belong?", "Is it true I don’t belong anywhere?", "What evidence shows someone wants me around?", "Am I holding back?", "What does God say about my place?", "Where could I begin to belong?"],
 name_example=["Ephesians 2:19", "<strong>Tom</strong> can write: “I am not a stranger. I am a member of God’s household, and I belong in His family.”"],
 hw_scriptures=["Ephesians 2:19", "1 Corinthians 12:18", "Romans 12:5"])

card(num=9, group="Other People", belief="People will leave me.", file="People-Will-Leave-Me",
 origins="Fear of being left often begins with real loss: a parent who left, died, or was emotionally absent; a divorce; repeated moves; or a partner who walked away. A child may conclude that people always leave, and that it must be because of something in them. As adults, people with this fear may cling tightly, test others, or avoid closeness altogether, and these patterns can sometimes bring about the very loss they fear.",
 teaches="Scripture is honest that people do leave, die, and fail us. David even wrote of being forsaken by father and mother. But God promises He will never leave or forsake His people. Isaiah says that even if a mother could forget her nursing child, God will not forget you. Jesus promised not to leave His followers as orphans. Human relationships are precious and uncertain, but there is One who will never walk away. That security can free us to love others without clinging or running.",
 key="Deuteronomy 31:6", also=["Hebrews 13:5", "Psalm 27:10", "Isaiah 49:15", "John 14:18"],
 self_statements=["Everyone I love eventually leaves.", "It’s only a matter of time.", "If I let someone close, they’ll abandon me.", "I have to keep people happy or they’ll go.", "I’m easy to walk away from.", "I can’t survive being left again."],
 errors=[["Fortune telling", "Predicting that people will leave without evidence."], ["Overgeneralization", "Believing that because some people left, everyone will."], ["Personalization", "Assuming people left because something is wrong with me."], ["Catastrophizing", "Imagining that being left would be unbearable and endless."]],
 questions=["Who left me in the past, and what were the real reasons?", "Who has stayed in my life, even through hard times?", "Am I clinging, testing, or pulling away to protect myself?", "What evidence do I have that this person will leave?", "What does God promise about His presence?", "How could I love more freely if I trusted God’s presence?"],
 truth="Some people have left me, and that was painful. But not everyone leaves, and God never will. He has promised to be with me always. I can love people without clinging or running, because my deepest security is in the One who stays.",
 hw_truths=["God will never leave or forsake me.", "God will not forget me.", "Not everyone leaves.", "My past losses do not predict every future.", "I can love without clinging.", "Jesus will not leave me an orphan."],
 log=["Who stayed today", "Each evening, write the names of people who showed up for you today, in large or small ways."],
 actions=[["List the people who stayed.", "Write the names of people who have stayed in your life through hard times. Thank God for each one."], ["Notice the test.", "When you are tempted to test someone’s loyalty, pause and instead tell them honestly what you need."], ["Practice letting go a little.", "Give someone space this week without texting or checking in excessively. Notice what happens."], ["Rest in God’s promise.", "Write Deuteronomy 31:6 on a card and read it whenever you fear being left."]],
 tracker="Someone who stayed",
 prayer="Lord, I am afraid of losing the people I love. Thank You that You will never leave me or forsake me. Heal the wounds from those who left, help me love without clinging, and let me rest in Your faithful presence. Amen.",
 songs=["stays", "alone", "held", "tender"],
 pearls=["loneliness", "friendship", "god-present-everywhere", "trust", "fear"],
 godly_counsel=[17, 5], reading="god-present-everywhere", listening="Anxiety",
 hw_questions=["Who left me, and why?", "Who has stayed?", "Am I clinging, testing, or pulling away?", "What evidence says this person will leave?", "What does God promise about His presence?", "How could I love more freely?"],
 name_example=["Deuteronomy 31:6", "<strong>Sarah</strong> can write: “The Lord goes with me. He will never leave me or forsake me.”"],
 hw_scriptures=["Deuteronomy 31:6", "Isaiah 49:15", "Psalm 27:10"])

card(num=10, group="Other People", belief="No one will care for me when I need them.", file="No-One-Will-Care-For-Me",
 origins="This belief often starts in homes where needs were ignored, dismissed, or punished, or where a child had to care for a parent instead of being cared for. Times of illness, crisis, or grief when no one showed up can deepen it. People who hold this belief often become fiercely self-reliant, never ask for help, and then feel confirmed when no one offers.",
 teaches="God invites us to cast all our anxiety on Him, because He cares for us. Jesus pointed to the birds of the air and reminded us that our Father feeds them, and we are worth much more. The Lord is near to all who call on Him. Scripture also calls believers to carry one another’s burdens; caring for each other is how God designed His family to work. People may have failed you, but God cares, and He often sends His care through people when we let them in.",
 key="1 Peter 5:7", also=["Psalm 55:22", "Matthew 6:26", "Psalm 145:18", "Galatians 6:2"],
 self_statements=["If I fall apart, no one will be there.", "I have to take care of myself because no one else will.", "Asking for help is pointless.", "People only show up when they need something.", "My needs are a burden to others.", "I’m on my own."],
 errors=[["Overgeneralization", "Deciding that because some people didn’t care, no one will."], ["Fortune telling", "Predicting that no one will help before I ask."], ["Discounting the positive", "Overlooking times when people did help."], ["Mind reading", "Assuming others see my needs as a burden."]],
 questions=["When were my needs ignored, and by whom?", "When has someone cared for me, even a little?", "Do I let people know when I need help?", "Am I so self-reliant that no one gets the chance to care?", "What does God say about His care for me?", "Who is one person I could ask for help?"],
 truth="There were times when no one cared for me as I needed. But God cares for me, and He often sends His care through people. I can let my needs be known, ask for help, and give others the chance to show up.",
 hw_truths=["God cares for me.", "I can cast my burdens on the Lord.", "My Father knows what I need.", "Asking for help is not weakness.", "God’s family is meant to carry burdens together.", "The Lord is near when I call."],
 log=["Care I received", "Each day, write one way someone cared for you, or one time you asked for help and what happened."],
 actions=[["Make a help list.", "Write the names of people you could call in a hard moment, even if you have never asked. Add a church or helpline."], ["Ask for something small.", "Ask one person for a small, specific favor this week. Note how they responded."], ["Tell someone how you are.", "When asked “How are you?” give one honest answer instead of “Fine.”"], ["Pray your needs.", "Each morning, tell God one specific need, following 1 Peter 5:7."]],
 tracker="A time someone cared",
 prayer="Father, I have felt alone in my needs for a long time. Thank You that You care for me and that I can bring every burden to You. Help me let others in, ask for help, and receive the care You send. Amen.",
 songs=["knows", "jesus", "held", "friend"],
 pearls=["help", "loneliness", "friendship", "prayer-answers-to", "god-all-loving"],
 godly_counsel=[22, 17], reading="help", listening="Depression",
 hw_questions=["When were my needs ignored?", "When has someone cared for me?", "Do I let people know my needs?", "Am I so self-reliant that no one can help?", "What does God say about His care?", "Who could I ask for help?"],
 name_example=["1 Peter 5:7", "<strong>Karen</strong> can write: “I can give my worries to God, because He cares for me.”"],
 hw_scriptures=["1 Peter 5:7", "Psalm 55:22", "Galatians 6:2"])

card(num=11, group="Other People", belief="Nobody loves me.", file="Nobody-Loves-Me",
 origins="This belief can grow from a childhood without warmth or affection, the loss of a spouse or parent, a painful breakup, or long seasons of loneliness. Depression can also color everything gray, so that even real love is hard to feel. When people feel unloved, they may withdraw, which leads to more loneliness and seems to prove the belief true.",
 teaches="The Bible declares that God has loved His people with an everlasting love. John marvels at the kind of love the Father has given, that we should be called children of God. Jesus said that as the Father loved Him, so He loves us. Even if mountains are shaken, God’s loving devotion will not depart. Human love may be missing or imperfect right now, but you are loved by God fully and personally. That love can also open your eyes to the people who do care for you.",
 key="1 John 3:1", also=["Jeremiah 31:3", "John 15:9", "Isaiah 54:10", "Psalm 103:13"],
 self_statements=["No one cares about me.", "If I died, no one would miss me.", "Everyone else is loved but me.", "People are nice to me only out of obligation.", "I’m completely alone.", "Even God doesn’t love me."],
 errors=[["Overgeneralization", "Using “nobody” and “never” when some people do care."], ["Emotional reasoning", "Believing I am unloved because I feel unloved."], ["Discounting the positive", "Explaining away kindness as obligation."], ["Mental filter", "Focusing on who doesn’t love me and overlooking who does."]],
 questions=["Is it true that nobody loves me, or that I don’t feel loved right now?", "Who has shown me care, even in small ways?", "Am I withdrawing in ways that make love harder to find?", "Could sadness or depression be affecting how I see things?", "What does God say about His love for me?", "What is one small step toward connection?"],
 truth="I feel unloved right now, and that is painful. But feelings are not the full truth. God has loved me with an everlasting love and calls me His child. I can look for the ways I am cared for and take small steps toward people.",
 hw_truths=["God has loved me with an everlasting love.", "I am called a child of God.", "Jesus loves me as the Father loves Him.", "Feeling unloved is not the same as being unloved.", "Some people do care about me.", "God’s love will not depart from me."],
 log=["Signs of love today", "Each evening, write one sign of love or care you noticed today, from God or from a person."],
 actions=[["Look for evidence.", "Write the names of people who have shown you any kindness in the last year. Ask yourself what each act says."], ["Reach out once.", "Send one message or make one call to someone you care about this week."], ["Read God’s love letter.", "Read 1 John 3:1 and Jeremiah 31:3 each morning and say, “This is true of me.”"], ["Get support for heavy sadness.", "If feeling unloved comes with deep sadness that won’t lift, talk with a doctor, pastor, or counselor."]],
 tracker="A sign of love I noticed",
 prayer="Father, I feel so unloved and alone. Thank You that You have loved me with an everlasting love and call me Your child. Open my eyes to Your love and to the people who care about me, and give me courage to reach out. Amen.",
 songs=["father", "conquer", "yousay", "lovesme"],
 pearls=["love-by-god", "loneliness", "god-all-loving", "depression-symptoms-of", "friendship"],
 godly_counsel=[17, 12], reading="love-by-god", listening="Depression",
 hw_questions=["Is it true nobody loves me, or that I don’t feel loved?", "Who has shown me care?", "Am I withdrawing?", "Could sadness be affecting how I see things?", "What does God say about His love?", "What small step toward connection can I take?"],
 name_example=["1 John 3:1", "<strong>Linda</strong> can write: “The Father has lavished His love on me. I am called His child, and that is what I am.”"],
 hw_scriptures=["1 John 3:1", "Jeremiah 31:3", "John 15:9"])

card(num=12, group="Other People", belief="People cannot be trusted.", file="People-Cannot-Be-Trusted",
 origins="This belief usually comes from betrayal: a parent who broke promises, abuse by someone who should have protected us, a spouse’s unfaithfulness, gossip, or being cheated. After being hurt, it makes sense to protect ourselves. But when the lesson becomes “no one can ever be trusted,” we can end up isolated, suspicious, and unable to receive the support we need.",
 teaches="Scripture is realistic about people. It warns that it is better to take refuge in the Lord than to trust in man, and Jesus told His followers to be shrewd as snakes and innocent as doves. Wisdom means trusting carefully, not blindly. But the Bible also calls us into community, forgiveness, and love. Our full trust belongs to God, who never fails. Because He is trustworthy, we can risk measured trust with people, give it gradually, and watch whether it is honored.",
 key="Psalm 56:3–4", also=["Proverbs 3:5–6", "Jeremiah 17:7", "Psalm 118:8", "Matthew 10:16"],
 self_statements=["Everyone has a hidden agenda.", "If I trust, I’ll get hurt.", "People always let you down.", "I can only count on myself.", "Kindness is just a setup.", "It’s safer to keep everyone at arm’s length."],
 errors=[["Overgeneralization", "Deciding everyone is untrustworthy because some people betrayed me."], ["All-or-nothing thinking", "Believing I must either trust completely or not at all."], ["Mind reading", "Assuming people have bad motives without evidence."], ["Fortune telling", "Predicting betrayal before it happens."]],
 questions=["Who betrayed my trust, and what did I learn from it?", "Is there anyone who has proven trustworthy over time?", "Can I trust someone a little without trusting them with everything?", "What signs show that a person is trustworthy?", "What does God say about where my full trust belongs?", "What small risk of trust could I take with a safe person?"],
 truth="Some people have betrayed me, and I am wise to be careful. But not everyone is untrustworthy. My full trust belongs to God, who never fails. Because I am secure in Him, I can offer trust to people gradually and wisely, and watch whether it is honored.",
 hw_truths=["When I am afraid, I can trust God.", "Wisdom means trusting carefully, not never.", "Some people have proven trustworthy.", "Trust can be built step by step.", "My security rests in God.", "Forgiving does not require trusting blindly."],
 log=["Trust I tested", "Each day, write one small way you trusted someone and whether that trust was honored."],
 actions=[["Make a trust ladder.", "List small, medium, and large things you could trust someone with. Start with one small item this week."], ["Name who has been faithful.", "Write the names of people who have kept their word to you, even in small things."], ["Watch, then decide.", "With a new person, look for consistency between words and actions over time before deciding."], ["Get help for deep wounds.", "If betrayal or abuse still feels raw, talk with a counselor or pastor about healing and safe boundaries."]],
 tracker="Trust that was honored",
 prayer="Lord, I have been hurt by people I trusted. Thank You that You are completely trustworthy. Heal my wounds, give me wisdom to see who is safe, and courage to trust carefully again. Amen.",
 songs=["voice", "want", "fear", "eyes"],
 pearls=["trust", "friendship", "wisdom", "forgiveness", "refuge-safety"],
 godly_counsel=[14, 31], reading="trust", listening="Anxiety",
 hw_questions=["Who betrayed my trust, and what did I learn?", "Who has proven trustworthy?", "Can I trust someone a little?", "What signs show someone is trustworthy?", "Where does my full trust belong?", "What small risk of trust can I take?"],
 name_example=["Psalm 56:3–4", "<strong>David</strong> can write: “When I am afraid, I put my trust in God. With Him, I can risk trusting wisely.”"],
 hw_scriptures=["Psalm 56:3–4", "Proverbs 3:5–6", "Matthew 10:16"])

card(num=13, group="Other People", belief="My needs don’t matter.", file="My-Needs-Dont-Matter",
 origins="Many people learn this in families where their needs were ignored, mocked, or treated as selfish, or where they had to take care of a parent or siblings. Some were praised for always putting others first, so they learned that having needs was bad. As adults they may say yes to everything, neglect rest and health, and feel resentful or exhausted without knowing why.",
 teaches="Scripture shows a God who cares about our needs. He opens His hand and satisfies the desires of every living thing, and He promises to supply all our needs in Christ. When Elijah was exhausted and despairing, God gave him food and sleep before anything else. Jesus said to love your neighbor as yourself, which assumes that caring for yourself is normal. Serving others is good, but God never asks you to pretend you have no needs. Your needs matter to Him.",
 key="Philippians 4:19", also=["Psalm 145:15–16", "1 Kings 19:5–7", "Mark 12:31", "Matthew 11:28–30"],
 self_statements=["Other people’s needs come first, always.", "It’s selfish to want anything for myself.", "I don’t want to be a bother.", "I can rest when everything else is done.", "If I say no, people will be upset.", "My feelings aren’t important."],
 errors=[["All-or-nothing thinking", "Believing I must either meet every need of others or be selfish."], ["Should statements", "Telling myself I should never need anything."], ["Discounting the positive", "Ignoring the times my needs were met and it was good."], ["Mind reading", "Assuming others will be upset if I express a need."]],
 questions=["Where did I learn that my needs don’t matter?", "What needs am I ignoring right now?", "Is caring for myself really selfish?", "How did God care for Elijah when he was exhausted?", "What happens to me when I ignore my needs for too long?", "What is one need I could honestly express this week?"],
 truth="I care about others, and that is good. But my needs matter too, to God and to the people who love me. God supplies my needs and cares about my body, rest, and feelings. I can take care of myself and still serve others.",
 hw_truths=["God will supply all my needs.", "My needs matter to God.", "Rest and care are not selfish.", "I can love others as I love myself.", "Saying no can be healthy.", "Jesus offers me rest."],
 log=["A need I met", "Each day, write one need you noticed in yourself and what you did about it."],
 actions=[["Name your needs.", "Write a list of what you need: rest, food, friendship, quiet, help. Circle one to address this week."], ["Say one honest no.", "Decline one request this week that you would normally accept out of guilt. Notice what happens."], ["Schedule rest.", "Put one hour of rest or enjoyment on your calendar and keep it like an appointment."], ["Express a need.", "Tell one trusted person about a need you have, and let them help."]],
 tracker="A need I took care of",
 prayer="Father, I have treated my needs as unimportant for so long. Thank You that You care about all of me and promise to supply what I need. Teach me to rest, to speak up, and to receive care without guilt. Amen.",
 songs=["knows", "worn", "father", "great"],
 pearls=["self-esteem-low", "help", "self-sacrifice", "tired", "love-general"],
 godly_counsel=[24, 33], reading="tired", listening="Depression",
 hw_questions=["Where did I learn my needs don’t matter?", "What needs am I ignoring?", "Is caring for myself selfish?", "How did God care for Elijah?", "What happens when I ignore my needs?", "What need can I express this week?"],
 name_example=["Philippians 4:19", "<strong>Maria</strong> can write: “God will supply what I need. My needs matter to Him, and I can take care of them.”"],
 hw_scriptures=["Philippians 4:19", "1 Kings 19:5–7", "Mark 12:31"])

# ---------------- THE WORLD & THE FUTURE ----------------
card(num=14, group="The World & the Future", belief="Things will always go badly.", file="Things-Will-Always-Go-Badly",
 origins="This belief often follows a long run of hardship: repeated losses, chronic illness, financial struggles, or a childhood where good things rarely lasted. When disappointment comes again and again, the mind learns to expect it, partly to avoid being caught off guard. Over time hopelessness can feel like realism, and good things get dismissed as flukes.",
 teaches="Scripture does not deny that life brings trouble, but it insists that trouble is not the final word. God told His people in exile that He had plans to give them a future and a hope. Weeping may stay the night, but joy comes in the morning. God promises to do new things, even making a way in the wilderness. Paul wrote that God works all things together for the good of those who love Him. Bad seasons are real, but they are seasons, and God is at work in them.",
 key="Jeremiah 29:11", also=["Romans 8:28", "Lamentations 3:22–23", "Psalm 30:5", "Isaiah 43:19"],
 self_statements=["Nothing ever works out for me.", "As soon as things get better, something will ruin it.", "Why hope? It never turns out.", "My life is just one bad thing after another.", "Good things don’t last.", "It will always be like this."],
 errors=[["Fortune telling", "Predicting that the future will be as bad as the past."], ["Overgeneralization", "Using “always” and “never” about my life."], ["Mental filter", "Seeing only what goes wrong and overlooking what goes right."], ["Discounting the positive", "Calling good things luck or temporary."]],
 questions=["Is it true that things always go badly, or only often?", "What has gone well, even in small ways, this past year?", "What season of my life was better than I expected?", "What does God say about my future?", "Am I protecting myself from disappointment by expecting the worst?", "What would hope look like today?"],
 truth="I have been through many hard things, and more may come. But “always” is not true. Good things have happened, and God has promised a future and a hope. Hard seasons do not last forever, and God is at work even now.",
 hw_truths=["God has plans to give me a future and a hope.", "Joy comes in the morning.", "His mercies are new every morning.", "Hard seasons are seasons.", "God is doing something new.", "Good things are real, not just luck."],
 log=["What went right today", "Each evening, write three things that went right today, even small ones."],
 actions=[["Keep a “good things” journal.", "Each night for two weeks, write three good things that happened. Read the whole list at the end."], ["Remember a turnaround.", "Write about a time something you dreaded turned out better than expected."], ["Plan one good thing.", "Schedule one small thing you can look forward to this week."], ["Get help for lasting hopelessness.", "If hopelessness is heavy or constant, talk with a doctor, pastor, or counselor."]],
 tracker="Something that went right",
 prayer="Lord, I have come to expect the worst. Thank You that You have plans to give me a future and a hope. Open my eyes to the good You are doing, and give me hope for tomorrow. Amen.",
 songs=["glorious", "allnew", "even", "lives"],
 pearls=["hopeless", "hardship", "plans", "thinking-healthy", "joy"],
 godly_counsel=[30, 12], reading="hopeless", listening="Depression",
 hw_questions=["Is it true things always go badly?", "What has gone well this year?", "When was life better than I expected?", "What does God say about my future?", "Am I expecting the worst to protect myself?", "What would hope look like today?"],
 name_example=["Jeremiah 29:11", "<strong>Tom</strong> can write: “God knows the plans He has for me. He is giving me a future and a hope.”"],
 hw_scriptures=["Jeremiah 29:11", "Psalm 30:5", "Isaiah 43:19"])

card(num=15, group="The World & the Future", belief="The world is unsafe.", file="The-World-Is-Unsafe",
 origins="This belief often comes from real danger: abuse, violence, a frightening accident, a crime, a natural disaster, or growing up in a chaotic home. Constant news of tragedy can strengthen it. After danger, the body stays on alert, scanning for threats. That alertness helped us survive, but when it never shuts off, it can keep us anxious, isolated, and unable to enjoy life.",
 teaches="Scripture is honest that the world has dangers; Jesus said that in this world we will have trouble. But He added that He has overcome the world. The psalmist found shelter in the shadow of the Almighty and could lie down and sleep in peace because the Lord made him dwell in safety. The name of the Lord is a strong tower. God does not promise that nothing bad will ever happen, but He promises His presence, and our ultimate safety rests in Him.",
 key="Psalm 91:1–2", also=["John 16:33", "Psalm 4:8", "Proverbs 18:10", "Isaiah 26:3"],
 self_statements=["Something bad could happen at any moment.", "I have to stay on guard.", "It’s not safe to go out.", "People are dangerous.", "If I relax, I’ll get hurt.", "Nowhere is safe."],
 errors=[["Overgeneralization", "Deciding that because danger happened once, it is everywhere."], ["Catastrophizing", "Treating unlikely dangers as certain."], ["Mental filter", "Focusing on threats and overlooking signs of safety."], ["Emotional reasoning", "Believing I am in danger because I feel afraid."]],
 questions=["What happened that taught me the world is unsafe?", "Is that danger present now, or am I reacting to the past?", "What reasonable steps keep me safe, and which ones are excessive?", "Where have I been safe recently?", "What does God promise about His protection and presence?", "What could I enjoy if I felt a little safer?"],
 truth="There are real dangers in the world, and I have been hurt before. But I am not in danger every moment. I can take sensible precautions and then rest, because God is my refuge. He has overcome the world, and I can find peace in Him.",
 hw_truths=["God is my refuge and fortress.", "Jesus has overcome the world.", "I can lie down in peace.", "Feeling afraid is not the same as being in danger.", "I can take wise steps and then rest.", "The name of the Lord is a strong tower."],
 log=["Where I was safe today", "Each evening, write the places and moments you were safe today."],
 actions=[["Separate past from present.", "Write what happened in the past that frightened you. Then write what is different about your situation now."], ["Take one brave step.", "Choose one place or activity you avoid out of fear that is actually safe, and do it this week with support if needed."], ["Limit the news.", "Choose a set time for news once a day instead of checking all day."], ["Get help for trauma.", "If past danger still triggers strong fear, flashbacks, or nightmares, talk with a counselor trained to help."]],
 tracker="A moment I felt safe",
 prayer="Lord, I feel unsafe so much of the time. Thank You that You are my refuge and that Jesus has overcome the world. Calm my body and mind, give me wisdom to stay safe, and help me rest in Your shelter. Amen.",
 songs=["fear", "battle", "power", "eyes"],
 pearls=["refuge-safety", "protection", "fear", "peace", "trust"],
 godly_counsel=[5, 27], reading="refuge-safety", listening="Anxiety",
 hw_questions=["What taught me the world is unsafe?", "Is that danger present now?", "Which precautions are sensible and which are excessive?", "Where have I been safe recently?", "What does God promise about His protection?", "What could I enjoy if I felt safer?"],
 name_example=["Psalm 91:1–2", "<strong>Karen</strong> can write: “The Lord is my refuge and my fortress. I can rest in His shelter today.”"],
 hw_scriptures=["Psalm 91:1–2", "John 16:33", "Psalm 4:8"])

card(num=16, group="The World & the Future", belief="Something terrible is going to happen.", file="Something-Terrible-Is-Going-To-Happen",
 origins="A sense of coming doom often follows a sudden shock, such as an unexpected death, diagnosis, or accident, which teaches the mind that disaster can strike without warning. It can also grow in homes where parents were constantly worried, or where something bad really did happen often. Worry can feel like protection, as if expecting the worst could prevent it.",
 teaches="Jesus told His followers not to worry about tomorrow, because each day has enough trouble of its own. Paul urged believers to bring every anxious thought to God in prayer with thanksgiving, and promised that God’s peace would guard their hearts and minds. The psalmist describes a person who does not fear bad news because his heart is steady, trusting in the Lord. Worry cannot add a single hour to life. God does not ask us to pretend bad things never happen; He asks us to trust Him with tomorrow.",
 key="Matthew 6:34", also=["Philippians 4:6–7", "Psalm 112:7", "Matthew 6:27", "2 Timothy 1:7"],
 self_statements=["I just know something bad is coming.", "If I stop worrying, it will happen.", "Every phone call might be bad news.", "Things are too good; something will go wrong.", "I need to be prepared for the worst.", "I can’t shake this feeling of dread."],
 errors=[["Fortune telling", "Predicting disaster without evidence."], ["Catastrophizing", "Jumping from a small worry to the worst possible outcome."], ["Emotional reasoning", "Believing danger is coming because I feel dread."], ["Magical thinking", "Believing my worry somehow prevents bad things."]],
 questions=["What evidence do I have that something terrible is about to happen?", "How many times have I felt this dread and nothing happened?", "Does my worrying actually prevent anything?", "If something hard did happen, how might God help me through it?", "What does Jesus say about tomorrow?", "What can I do today instead of worrying about tomorrow?"],
 truth="Hard things can happen, and I cannot prevent every one. But this feeling of dread is not a prophecy, and worry does not protect me. God holds tomorrow. I can bring my fears to Him, live today, and trust Him to help me with whatever comes.",
 hw_truths=["Tomorrow will take care of itself.", "God’s peace can guard my heart and mind.", "Dread is a feeling, not a prediction.", "Worry cannot add an hour to my life.", "God holds my future.", "I can live today."],
 log=["Fears and outcomes", "Each day, write down any fear about something terrible happening. A week later, note whether it happened."],
 actions=[["Test your predictions.", "Keep a list of the bad things you predict for two weeks. At the end, count how many actually happened."], ["Set a worry time.", "Give yourself 15 minutes a day to write worries and pray over them. Outside that time, gently postpone worry."], ["Pray it through.", "When dread rises, pray Philippians 4:6–7 aloud, naming each fear and thanking God for one thing."], ["Get help for constant dread.", "If dread is constant or comes with panic attacks, talk with a doctor or counselor."]],
 tracker="A fear that did not come true",
 prayer="Lord, I am so often afraid that something terrible is coming. Thank You that You hold tomorrow. I give You my fears today. Guard my heart and mind with Your peace, and help me live this day with You. Amen.",
 songs=["liar", "battle", "already", "lives"],
 pearls=["anxiety-worry", "fear", "peace", "trust", "thinking-healthy"],
 godly_counsel=[5, 29], reading="anxiety-worry", listening="Anxiety",
 hw_questions=["What evidence says something terrible is coming?", "How often has this dread come true?", "Does worrying prevent anything?", "How might God help me if something hard happened?", "What does Jesus say about tomorrow?", "What can I do today?"],
 name_example=["Matthew 6:34", "<strong>James</strong> can write: “I don’t have to carry tomorrow today. God will be with me when it comes.”"],
 hw_scriptures=["Matthew 6:34", "Philippians 4:6–7", "Psalm 112:7"])

# ---------------- RULES I LIVE BY ----------------
card(num=17, group="Rules I Live By", belief="I must be perfect.", file="I-Must-Be-Perfect",
 origins="Perfectionism often grows in homes where love or approval seemed to depend on performance, where mistakes were criticized harshly, or where a child tried to keep chaos at bay by being “good.” Schools, sports, workplaces, and even churches can reward it. Perfectionism can look like high standards, but underneath is often fear of failure, rejection, or shame.",
 teaches="Scripture teaches that all have sinned and fall short, and that we are made right with God freely by His grace, not by being flawless. The Lord has compassion on His children, because He knows how we are formed and remembers that we are dust. Paul was confident that God, who began a good work in believers, will complete it. Doing our best is good; demanding perfection of ourselves is a burden God never placed on us. Jesus invites us to take His yoke, which is easy and light.",
 key="Psalm 103:13–14", also=["Romans 3:23–24", "Philippians 1:6", "2 Corinthians 12:9", "Matthew 11:28–30"],
 self_statements=["If it isn’t perfect, it’s a failure.", "I can’t let anyone see my flaws.", "I have to do it all myself so it’s done right.", "Good enough isn’t good enough.", "If I make a mistake, people will think less of me.", "I should be able to do better."],
 errors=[["All-or-nothing thinking", "Seeing anything less than perfect as total failure."], ["Should statements", "Living by rigid rules about how I must perform."], ["Discounting the positive", "Overlooking what I did well because of one flaw."], ["Mind reading", "Assuming others judge me harshly for small mistakes."]],
 questions=["Who taught me that I had to be perfect?", "What am I afraid will happen if I am not perfect?", "Do I hold others to the same standard I hold myself?", "What does God expect of me, and what does His grace provide?", "What has perfectionism cost me?", "What would “good enough” look like in one area this week?"],
 truth="I want to do things well, and that is good. But I am human, and God knows I am made of dust. He accepts me by grace, not by flawless performance. I can do my best, make mistakes, and rest in His grace.",
 hw_truths=["God knows I am dust and has compassion on me.", "I am made right by grace, not perfection.", "God will finish the work He started in me.", "Good enough is often good enough.", "Mistakes are part of being human.", "Jesus’ yoke is easy and light."],
 log=["Good enough today", "Each day, write one thing you allowed to be “good enough” and what happened as a result."],
 actions=[["Do something imperfectly on purpose.", "Choose one low-stakes task, such as sending an email without rereading it three times, and let it be good enough."], ["Count the cost.", "Write what perfectionism has cost you in time, rest, relationships, or joy."], ["Share a flaw.", "Tell one trusted person about a mistake you made this week. Notice how they respond."], ["Set a time limit.", "Give a task a set amount of time, and stop when the time is up."]],
 tracker="Something I let be good enough",
 prayer="Father, I have tried so hard to be perfect, and I am tired. Thank You that You know I am dust and that Your grace covers me. Help me do my best, accept my limits, and rest in Your love. Amen.",
 songs=["wins", "truth", "broken", "amazing"],
 pearls=["grace", "thinking-unhealthy", "humility", "tired", "self-esteem-low"],
 godly_counsel=[29, 24], reading="grace", listening="Anxiety",
 hw_questions=["Who taught me I had to be perfect?", "What am I afraid will happen if I’m not?", "Do I hold others to the same standard?", "What does God’s grace provide?", "What has perfectionism cost me?", "What would good enough look like?"],
 name_example=["Psalm 103:13–14", "<strong>Linda</strong> can write: “God knows how I am made. He has compassion on me when I fall short.”"],
 hw_scriptures=["Psalm 103:13–14", "Romans 3:23–24", "Philippians 1:6"])

card(num=18, group="Rules I Live By", belief="I must have everyone’s approval.", file="I-Must-Have-Everyones-Approval",
 origins="The need for approval often begins with parents whose love seemed conditional, frequent criticism, or rejection by peers. A child who learns that keeping others happy keeps them safe may grow into an adult who can’t say no, avoids conflict, and feels crushed by any disapproval. Social media can intensify the hunger for likes and praise.",
 teaches="Paul asked whether he was seeking the approval of people or of God, and concluded that pleasing people could not be his goal. Proverbs warns that the fear of man is a snare, but trusting the Lord brings security. Scripture calls us to work wholeheartedly for the Lord rather than for people. God already approves of His children in Christ. That approval frees us to love and serve others without needing their applause, and to accept that not everyone will be pleased with us.",
 key="Galatians 1:10", also=["Proverbs 29:25", "Colossians 3:23", "1 Thessalonians 2:4", "Psalm 118:6"],
 self_statements=["If someone is upset with me, I’ve failed.", "I can’t say no.", "I need people to like me.", "I worry constantly about what others think.", "Criticism crushes me.", "I’ll go along to keep the peace."],
 errors=[["Mind reading", "Assuming people disapprove of me."], ["Catastrophizing", "Treating someone’s disapproval as a disaster."], ["Personalization", "Taking others’ moods as a judgment on me."], ["Should statements", "Believing I should please everyone."]],
 questions=["Whose approval did I need most growing up?", "Is it possible for anyone to please everyone?", "What am I afraid will happen if someone disapproves?", "Whose approval matters most, and do I already have it?", "What have I given up to keep others happy?", "Where could I be honest even if someone is not pleased?"],
 truth="I care what people think, and that is human. But I cannot please everyone, and I don’t need to. God already accepts me in Christ. His approval frees me to be honest, say no when I need to, and love others without needing their applause.",
 hw_truths=["I live for God’s approval, not man’s.", "The fear of man is a snare.", "God already accepts me in Christ.", "No one can please everyone.", "Disapproval is uncomfortable, not dangerous.", "I can say no and still be kind."],
 log=["When I sought approval", "Each day, write one time you did something mainly for approval, and one time you acted on your own convictions."],
 actions=[["Say one kind no.", "Decline one request this week that you would normally accept to avoid disapproval."], ["Share an honest opinion.", "Express a different opinion respectfully in a safe setting."], ["Notice the people-pleasing.", "Each time you change your behavior to win approval, ask, “Whose approval am I seeking?”"], ["Rest in God’s approval.", "Read Galatians 1:10 each morning and remind yourself that God already accepts you in Christ."]],
 tracker="A time I acted on my convictions",
 prayer="Lord, I have spent so much energy trying to please everyone. Thank You that I already have Your approval in Christ. Free me from the fear of man, and help me live honestly and lovingly for You. Amen.",
 songs=["greater", "yousay", "voice", "assurance"],
 pearls=["self-esteem-low", "fear", "humility", "love-by-god", "communication"],
 godly_counsel=[24, 10], reading="self-esteem-low", listening="Anxiety",
 hw_questions=["Whose approval did I need growing up?", "Can anyone please everyone?", "What am I afraid will happen if someone disapproves?", "Whose approval matters most?", "What have I given up to please others?", "Where could I be honest?"],
 name_example=["Galatians 1:10", "<strong>Mark</strong> can write: “I’m not living to please people. I already have God’s approval in Christ.”"],
 hw_scriptures=["Galatians 1:10", "Proverbs 29:25", "Colossians 3:23"])

card(num=19, group="Rules I Live By", belief="I must be in control.", file="I-Must-Be-In-Control",
 origins="The need for control often grows in chaotic or frightening homes, where a child tried to bring order by managing everything around them. It can also follow trauma, a sudden loss, or a time when things spun out of control. Control can feel like safety. But because so much in life is beyond our control, this belief often leads to anxiety, tension in relationships, and exhaustion.",
 teaches="Scripture teaches that we can make plans, but the Lord directs our steps. James warns against confident boasting about tomorrow and teaches us to say, “If the Lord is willing.” God tells us to be still and know that He is God. Trusting the Lord with all our heart rather than leaning on our own understanding is not passivity; it is placing control in better hands. We are responsible for our choices, but the outcome belongs to God.",
 key="Proverbs 16:9", also=["Proverbs 3:5–6", "Psalm 46:10", "James 4:13–15", "Matthew 6:27"],
 self_statements=["If I don’t handle it, it will fall apart.", "I can’t stand not knowing what will happen.", "Others won’t do it right.", "I have to plan for every possibility.", "Letting go feels dangerous.", "If I lose control, something bad will happen."],
 errors=[["Catastrophizing", "Believing disaster will follow if I loosen my grip."], ["Should statements", "Insisting things must go my way."], ["Fortune telling", "Predicting that others will fail if I don’t manage them."], ["Overestimating control", "Thinking I can prevent outcomes that are really in God’s hands."]],
 questions=["When did I learn that I had to be in control?", "What am I actually able to control, and what not?", "What does my need for control cost me and others?", "What happens when I try to control things I cannot?", "What does God say about who directs my steps?", "What is one thing I could release to God this week?"],
 truth="I am responsible for my own choices, and I can plan wisely. But I cannot control everything, and I don’t have to. God directs my steps and holds what I cannot. I can do my part and trust Him with the rest.",
 hw_truths=["I plan, and the Lord directs my steps.", "I can be still and know He is God.", "I am responsible for my choices, not every outcome.", "Letting go is trusting, not giving up.", "God holds what I cannot.", "Worry cannot add an hour to my life."],
 log=["What I released today", "Each day, write one thing you tried to control and one thing you chose to release to God."],
 actions=[["Draw the circle.", "Draw a circle. Inside, write what you can control. Outside, write what you can’t. Pray over the outside list."], ["Delegate one task.", "Let someone else do one task their way this week without correcting them."], ["Practice uncertainty.", "Make one small plan with an open end, such as trying a new restaurant without reading reviews."], ["Pray a release prayer.", "Each morning, name one worry and say, “Lord, I give this to You.”"]],
 tracker="Something I released",
 prayer="Lord, I hold on so tightly because I am afraid. Thank You that You direct my steps and hold what I cannot. Help me do my part, release the rest, and rest in Your care. Amen.",
 songs=["want", "held", "already", "eyes"],
 pearls=["trust", "plans", "will-of-god", "anxiety-worry", "peace"],
 godly_counsel=[5, 22], reading="trust", listening="Anxiety",
 hw_questions=["When did I learn I had to be in control?", "What can I control and what not?", "What does control cost me?", "What happens when I try to control the uncontrollable?", "Who directs my steps?", "What can I release this week?"],
 name_example=["Proverbs 16:9", "<strong>Maria</strong> can write: “I can make my plans, but the Lord directs my steps. I can trust Him with the outcome.”"],
 hw_scriptures=["Proverbs 16:9", "Proverbs 3:5–6", "Psalm 46:10"])

card(num=20, group="Rules I Live By", belief="I must not make mistakes.", file="I-Must-Not-Make-Mistakes",
 origins="Fear of mistakes often comes from harsh punishment, ridicule, or anger when we got something wrong as children. Some families or schools treated every error as a character flaw. Later, a person may avoid trying new things, procrastinate, redo work endlessly, or hide errors, all to avoid the shame that once came with mistakes.",
 teaches="James writes plainly that we all stumble in many ways. Scripture never pretends God’s people are error-free; it shows Him forgiving, teaching, and restoring them. When we sin, confession brings forgiveness and cleansing. When we simply make honest mistakes, God’s mercies are new every morning. The righteous fall and rise again. In Christ there is no condemnation. Mistakes are part of learning, not proof of failure, and God is patient with us as we grow.",
 key="James 3:2", also=["1 John 1:9", "Proverbs 24:16", "Lamentations 3:22–23", "Romans 8:1"],
 self_statements=["Mistakes are unacceptable.", "If I make a mistake, I’ll be humiliated.", "I’d rather not try than get it wrong.", "I go over things again and again to be sure.", "One error can ruin everything.", "I can’t forgive myself for mistakes."],
 errors=[["All-or-nothing thinking", "Treating one mistake as total failure."], ["Catastrophizing", "Imagining terrible consequences from small errors."], ["Labeling", "Calling myself stupid or useless after a mistake."], ["Should statements", "Insisting I should never get anything wrong."]],
 questions=["Who taught me that mistakes were unacceptable?", "What actually happened the last time I made a mistake?", "How do I treat other people when they make mistakes?", "What have I learned from past mistakes?", "What does God do with our mistakes and sins?", "What would I try if I weren’t afraid of mistakes?"],
 truth="I will make mistakes, because every person does. Mistakes are part of learning, not proof that I am a failure. God forgives my sins, is patient with my errors, and helps me grow. I can try, learn, and keep going.",
 hw_truths=["We all stumble in many ways.", "God forgives and cleanses me.", "Mistakes are part of learning.", "There is no condemnation in Christ.", "His mercies are new every morning.", "I can try without fear."],
 log=["Mistakes and lessons", "Each day, write one mistake you made and one thing you learned from it."],
 actions=[["Make a harmless mistake on purpose.", "Do something small imperfectly, such as mispronouncing a word or leaving a typo, and notice that nothing terrible happens."], ["Try something new.", "Attempt one new activity where you are a beginner."], ["Share a mistake.", "Tell one trusted person about a mistake and how you handled it."], ["Respond like a coach.", "After a mistake, write what a kind coach would say to you."]],
 tracker="A mistake I learned from",
 prayer="Father, I am so afraid of getting things wrong. Thank You that You know we all stumble, and that You forgive and restore. Help me try, learn, and grow without fear, resting in Your patience and grace. Amen.",
 songs=["wins", "younger", "east", "touched"],
 pearls=["forgiveness", "grace", "confession", "thinking-healthy", "humility"],
 godly_counsel=[14, 29], reading="grace", listening="Anxiety",
 hw_questions=["Who taught me mistakes were unacceptable?", "What happened the last time I made a mistake?", "How do I treat others’ mistakes?", "What have I learned from mistakes?", "What does God do with mistakes and sins?", "What would I try if I weren’t afraid?"],
 name_example=["James 3:2", "<strong>Tom</strong> can write: “Everyone stumbles, including me. God is patient with me as I learn.”"],
 hw_scriptures=["James 3:2", "1 John 1:9", "Romans 8:1"])

# ---------------- AFTER PAINFUL EXPERIENCES ----------------
card(num=21, group="After Painful Experiences", belief="It was my fault.", file="It-Was-My-Fault",
 origins="After abuse, an assault, an accident, a parent’s divorce, or a loved one’s death, many people blame themselves. Children especially assume they caused what happened, because it is less frightening than believing the adults around them were unsafe. Abusers often tell victims it was their fault. Self-blame can also feel like control: if it was my fault, maybe I can prevent it next time.",
 teaches="Scripture is clear that each person is responsible for his own wrongdoing; the guilt of one is not placed on another. If someone harmed you, the responsibility belongs to the person who did it. God is near to the brokenhearted, and Jesus came to bind up the brokenhearted and set captives free. Where we have truly done wrong, God forgives completely. But where we were wronged, He does not ask us to carry the blame. In Christ, there is no condemnation.",
 key="Ezekiel 18:20", also=["Psalm 34:18", "Isaiah 61:1", "Romans 8:1", "Genesis 50:20"],
 self_statements=["I should have stopped it.", "If I had been better, it wouldn’t have happened.", "I must have done something to cause it.", "I deserved what happened.", "I should have seen it coming.", "It’s my fault they left."],
 errors=[["Personalization", "Taking responsibility for something another person chose to do."], ["Hindsight bias", "Judging my past self by what I know now."], ["Emotional reasoning", "Believing I’m to blame because I feel guilty."], ["Should statements", "Insisting I should have been able to prevent it."]],
 questions=["Who actually made the choices that caused harm?", "What did I know, and what power did I have, at the time?", "Would I blame a child or friend in the same situation?", "Did someone tell me it was my fault, and why might they have said that?", "Is there anything I truly need to confess, and anything I need to set down?", "What does God say about the brokenhearted and about blame?"],
 truth="Something painful happened, and I have carried the blame for it. But responsibility belongs to the person who caused the harm, not to me. I did what I could with what I knew then. God is near to me in my pain, and He does not ask me to carry guilt that isn’t mine.",
 hw_truths=["The guilt of another is not mine to carry.", "God is near to the brokenhearted.", "I did what I could with what I knew.", "Feeling guilty does not make me guilty.", "Jesus came to heal the brokenhearted.", "In Christ there is no condemnation."],
 log=["Blame I set down", "Each day, write one self-blaming thought and answer it with a truth from this card."],
 actions=[["Draw the responsibility pie.", "Draw a circle and divide it among everyone and everything that contributed to what happened. Notice how small, or empty, your slice really is."], ["Write to your younger self.", "Write a short letter to yourself at the age it happened, telling that person what you know now."], ["Tell a safe person.", "Share your story, or part of it, with a counselor, pastor, or trusted friend who will listen without blame."], ["Get specialized help.", "If what happened was abuse or assault, a counselor trained in trauma can help you heal at a safe pace."]],
 tracker="A time I set down blame",
 prayer="Lord, I have blamed myself for what happened for so long. Thank You that You are near to the brokenhearted. Help me lay down guilt that is not mine, confess what is, and receive Your healing and peace. Amen.",
 songs=["younger", "clean", "breaker", "tender"],
 pearls=["guilt-shame", "child-abuse-neglect", "mercy", "forgiveness", "help"],
 godly_counsel=[27, 24], reading="guilt-shame", listening="Depression",
 hw_questions=["Who made the choices that caused harm?", "What did I know and what power did I have then?", "Would I blame a child or friend?", "Who told me it was my fault?", "Is there anything to confess, and anything to set down?", "What does God say about blame and the brokenhearted?"],
 name_example=["Psalm 34:18", "<strong>Sarah</strong> can write: “The Lord is near to me when my heart is broken. I don’t have to carry blame that isn’t mine.”"],
 hw_scriptures=["Ezekiel 18:20", "Psalm 34:18", "Isaiah 61:1"])

card(num=22, group="After Painful Experiences", belief="What happened makes me dirty or bad.", file="What-Happened-Makes-Me-Dirty-Or-Bad",
 origins="This belief often follows sexual abuse, assault, betrayal, or humiliation. Shame can attach itself to the person who was hurt rather than to the person who did the harm. Abusers sometimes tell victims they are dirty or that no one will want them. Religious messages about purity, when misapplied, can deepen the feeling of being stained or ruined.",
 teaches="In the Gospels, Jesus touched people others considered unclean and said, “Be clean!” He was not made dirty by them; they were made clean by Him. Those who look to the Lord are radiant, and their faces are never covered with shame. God gives a crown of beauty instead of ashes. In Christ, anyone is a new creation, and believers can draw near to God with hearts sprinkled clean. What was done to you does not make you dirty, and nothing you have done is beyond His cleansing.",
 key="Psalm 34:5", also=["Mark 1:41", "Isaiah 61:3", "2 Corinthians 5:17", "Hebrews 10:22"],
 self_statements=["I’m ruined.", "No one would want me if they knew.", "I feel dirty no matter what I do.", "I’m damaged goods.", "God must see me as stained.", "What happened is who I am now."],
 errors=[["Emotional reasoning", "Believing I am dirty because I feel dirty."], ["Labeling", "Calling myself ruined or damaged because of what happened."], ["Personalization", "Taking on shame that belongs to the person who harmed me."], ["Overgeneralization", "Letting one experience define my whole identity."]],
 questions=["Whose shame am I carrying: mine or the person who hurt me?", "Who told me I was dirty or ruined?", "How did Jesus treat people others called unclean?", "Would I see a friend as dirty if this had happened to her or him?", "What does God say about those who look to Him?", "What would it mean to see myself as God sees me?"],
 truth="Something painful and wrong happened. The shame belongs to the one who did it, not to me. Jesus is not repelled by me; He reaches out and makes me clean. I am not ruined. In Christ I am a new creation, and my face does not have to be covered with shame.",
 hw_truths=["What was done to me does not make me dirty.", "Jesus touches me and says, “Be clean!”", "Those who look to Him are radiant.", "I am a new creation in Christ.", "God gives beauty for ashes.", "The shame belongs to the one who harmed me."],
 log=["Shame and truth", "Each day, write one moment when shame came up, and one truth from this card that answers it."],
 actions=[["Return the shame.", "Write what happened and, next to it, write who is responsible. Then write, “This shame belongs to them, not to me.”"], ["Read Mark 1:40–42.", "Read how Jesus touched the man with leprosy. Write what it shows you about how Jesus sees you."], ["Care for your body.", "Do one kind thing for your body this week, such as a warm bath, rest, or a walk, treating it as something God made good."], ["Get trauma-informed help.", "Healing from abuse or assault is hard to do alone. A counselor trained in trauma can walk with you at a safe pace."]],
 tracker="A moment I saw myself as clean",
 prayer="Lord Jesus, I have felt dirty and ruined because of what happened. Thank You that You reached out and touched those others called unclean. Lift my shame, heal my wounds, and help me see myself as You see me: clean, loved, and new. Amen.",
 songs=["clean", "name", "chains", "amazing"],
 pearls=["guilt-shame", "child-abuse-neglect", "born-again", "grace", "love-by-god"],
 godly_counsel=[24, 27], reading="guilt-shame", listening="Depression",
 hw_questions=["Whose shame am I carrying?", "Who told me I was dirty?", "How did Jesus treat people called unclean?", "Would I see a friend as dirty?", "What does God say about those who look to Him?", "What would it mean to see myself as God does?"],
 name_example=["Psalm 34:5", "<strong>Linda</strong> can write: “When I look to the Lord, my face does not have to be covered with shame.”"],
 hw_scriptures=["Psalm 34:5", "Mark 1:41", "2 Corinthians 5:17"])

if __name__ == "__main__":
    pearls = json.loads((ROOT / "tools/pearls-topics.json").read_text())
    music = json.loads((ROOT / "tools/music-catalog.json").read_text())
    gc = json.loads((ROOT / "tools/godly-counsel-chapters.json").read_text())
    order = ["belief", "file", "num", "group", "origins", "teaches", "key", "also", "self_statements", "errors", "questions", "truth", "hw_truths", "log", "actions", "tracker", "prayer", "songs", "pearls", "meta", "godly_counsel", "reading", "listening", "hw_questions", "name_example", "hw_scriptures"]
    for d in CARDS:
        d["meta"] = "Christian belief counseling for “%s” with BSB scriptures, questions, songs, and practical homework." % d["belief"]
        assert all(k in pearls for k in d["pearls"] + [d["reading"]]), (d["num"], d["pearls"])
        assert [music[k][3] for k in d["songs"]] == ["contemporary"] * 3 + ["classic"], (d["num"], d["songs"])
        assert all(str(n) in gc for n in d["godly_counsel"]), d["num"]
        assert len(d["actions"]) == 4 and len(d["errors"]) == 4, d["num"]
        folder = ROOT / "tools" / SETS[d["group"]]
        folder.mkdir(exist_ok=True)
        (folder / ("%03d.json" % d["num"])).write_text(json.dumps({k: d[k] for k in order}, ensure_ascii=False, indent=1))
    print("wrote", len(CARDS), "cards")
